package com.securelock.app;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.view.accessibility.AccessibilityManager;import android.widget.*;import java.text.DateFormat;import java.util.Date;
public class MainActivity extends Activity {private LinearLayout list;private TextView diag;
 @Override protected void onCreate(Bundle b){super.onCreate(b);build();startServiceSafe();}
 @Override protected void onResume(){super.onResume();if(diag!=null)refresh();}
 private void build(){ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);list.setPadding(24,24,24,30);list.setBackgroundColor(Color.rgb(11,18,32));sc.addView(list);TextView t=new TextView(this);t.setText("SecureLock 1.1");t.setTextColor(Color.WHITE);t.setTextSize(30);t.setGravity(Gravity.CENTER);list.addView(t,lp());TextView st=new TextView(this);st.setText("Reliability & security diagnostics");st.setTextColor(Color.LTGRAY);st.setGravity(Gravity.CENTER);list.addView(st,lp());diag=new TextView(this);diag.setTextColor(Color.WHITE);diag.setTextSize(15);diag.setPadding(0,20,0,20);list.addView(diag,lp());button("Set / Change PIN",v->setPin());button("Test SecureLock Lock Screen",v->LockActivity.requestLaunch(this,"manual test"));button("Start / Restart Security Service",v->startServiceSafe());button("Enable Accessibility Protection",v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));button("Allow Display Over Other Apps",v->{if(Build.VERSION.SDK_INT>=23)startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));});button("Enable screen-off locking",v->{SecureLockPrefs.setScreenLockEnabled(this,true);refresh();});button("Disable screen-off locking",v->{SecureLockPrefs.setScreenLockEnabled(this,false);refresh();});button("Refresh diagnostics",v->refresh());TextView note=new TextView(this);note.setText("\nImportant: SecureLock is an additional app-level layer. It does not replace Android's system credential. Android requires you to enable Accessibility manually and may restrict background activity launches.");note.setTextColor(Color.LTGRAY);list.addView(note,lp());setContentView(sc);refresh();}
 private void refresh(){boolean pin=SecureLockPrefs.hasPin(this),enabled=SecureLockPrefs.isEnabled(this),overlay=Build.VERSION.SDK_INT<23||Settings.canDrawOverlays(this),access=accessibilityEnabled();long ss=SecureLockPrefs.serviceStartTime(this),et=SecureLockPrefs.eventTime(this);diag.setText("SECURITY DIAGNOSTICS\n\n"+line("PIN configured",pin)+line("PIN protection enabled",enabled)+line("Service start recorded",ss>0)+"Service start: "+fmt(ss)+"\n"+line("Screen-off locking",SecureLockPrefs.screenLockEnabled(this))+line("Overlay permission",overlay)+line("Accessibility service",access)+"Boot events recorded: "+SecureLockPrefs.boots(this)+"\nLast event time: "+fmt(et)+"\nLast event: "+SecureLockPrefs.lastEvent(this)+"\n\nService start time is diagnostic evidence, not proof that the service is currently alive. Confirm the ongoing notification too.");}
 private String line(String s,boolean b){return s+": "+(b?"YES / ACTIVE":"NO / NEEDS ATTENTION")+"\n";}private String fmt(long x){return x==0?"not recorded":DateFormat.getDateTimeInstance().format(new Date(x));}
 private boolean accessibilityEnabled(){AccessibilityManager am=(AccessibilityManager)getSystemService(ACCESSIBILITY_SERVICE);if(am==null||!am.isEnabled())return false;String e=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);String target=getPackageName()+"/"+SecureAccessibilityService.class.getName();return e!=null&&e.toLowerCase().contains(target.toLowerCase());}
 private void setPin(){EditText e=new EditText(this);e.setHint("Enter 6–12 digit PIN");e.setInputType(2);new AlertDialog.Builder(this).setTitle("Set SecureLock PIN").setView(e).setPositiveButton("Save",(d,w)->{String p=e.getText().toString();if(!p.matches("\\d{6,12}")){new AlertDialog.Builder(this).setMessage("Use a PIN of 6–12 digits.").setPositiveButton("OK",null).show();return;}try{SecureLockPrefs.savePin(this,p);SecureLockPrefs.event(this,"PIN configured");refresh();}catch(Exception ex){new AlertDialog.Builder(this).setMessage("Could not save PIN").setPositiveButton("OK",null).show();}}).setNegativeButton("Cancel",null).show();}
 private void startServiceSafe(){Intent i=new Intent(this,SecureLockService.class);try{if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(RuntimeException e){SecureLockPrefs.event(this,"Manual service start failed: "+e.getClass().getSimpleName());}if(diag!=null)refresh();}
 private void button(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(l);list.addView(b,lp());}private LinearLayout.LayoutParams lp(){return new LinearLayout.LayoutParams(-1,-2);}
}
